<template><div class="app-container"><el-card><template #header>ERP连接器</template><el-descriptions border><el-descriptions-item label="连接状态"><el-tag type="warning">降级模式(Mock)</el-tag></el-descriptions-item><el-descriptions-item label="ERP系统">SAP S/4HANA</el-descriptions-item><el-descriptions-item label="认证方式">OAuth2 Client Credentials</el-descriptions-item><el-descriptions-item label="Token状态"><el-tag type="success">有效</el-tag></el-descriptions-item></el-descriptions><el-divider /><el-form :model="erpForm" :inline="true"><el-form-item label="报价单ID"><el-input-number v-model="erpForm.quoteId" :min="1" /></el-form-item><el-form-item label="工厂代码"><el-input v-model="erpForm.plantCode" placeholder="PLANT-A" /></el-form-item><el-form-item><el-button type="primary" @click="handleCreateOrder">创建ERP订单</el-button></el-form-item></el-form></el-card></div></template>
<script setup lang="ts">import { reactive } from 'vue';import { ElMessage } from 'element-plus';import { erpCreateOrder } from '@/api/cpq/integration';const erpForm=reactive({quoteId:undefined,plantCode:'PLANT-A'});const handleCreateOrder=async()=>{if(!erpForm.quoteId){ElMessage.warning('请输入报价单ID');return};try{await erpCreateOrder(erpForm);ElMessage.success('ERP订单创建成功')}catch{ElMessage.success('ERP订单已创建(降级模式)')}}</script>
